const $=s=>document.querySelector(s),seed=()=>[{id:'482d0c34-4979-4525-88e8-0a590c98f131',name:'Old North Observatory',kind:'point',latitude:51.5074,longitude:-0.1278},{id:'4b772e65-a55c-47b6-9aa4-d6814d1f24c0',name:'Rivergate Keep',kind:'point',latitude:48.8566,longitude:2.3522}];let locations=seed(),audit=[];const subject='demo-editor-subject';const sample={name:'Westbridge Aqueduct',kind:'point',latitude:50.1109,longitude:8.6821};$('#body').value=JSON.stringify(sample,null,2);
function uuid(){return crypto.randomUUID()}
function render(){const current=$('#locationid').value;$('#locationid').replaceChildren();locations.forEach(l=>$('#locationid').add(new Option(l.name+' / '+l.id.slice(0,8),l.id)));if(locations.some(l=>l.id===current))$('#locationid').value=current;$('#count').textContent=locations.length;$('#locationlist').replaceChildren();locations.forEach(l=>{const row=document.createElement('div');row.className='locationrow';const name=document.createElement('span');name.textContent=l.name;const meta=document.createElement('small');meta.textContent=l.id+' · '+l.latitude+', '+l.longitude;row.append(name,meta);$('#locationlist').append(row)});$('#audit').textContent=audit.length?audit.map(a=>JSON.stringify(a)).join('\n'):'No simulated changes yet.'}
function operation(){const o=$('#operation').value;$('#bodylabel').hidden=!['create','update'].includes(o);$('#idlabel').hidden=!['read','update','delete'].includes(o);if(o==='update')bodyForId();$('#feedback').textContent=''}
function bodyForId(){const l=locations.find(l=>l.id===$('#locationid').value);if(l){const {id,...rest}=l;$('#body').value=JSON.stringify(rest,null,2)}}
$('#operation').onchange=operation;$('#locationid').onchange=()=>{if($('#operation').value==='update')bodyForId()};
$('#reset').onclick=()=>{locations=seed();audit=[];render();$('#feedback').textContent='Sample locations and local audit examples reset. No remote data was changed.'};
function answer(status,body,id){$('#status').textContent=status;$('#result').textContent=JSON.stringify(body,null,2);$('#responsemeta').textContent='X-Request-Id: '+id+' · environment: '+$('#env').value+' · LOCAL SIMULATION';$('#feedback').textContent='Completed local simulation: '+status+'. No network request was sent.'}
function validBody(x){return x&&typeof x.name==='string'&&x.name.trim().length>0&&x.name.length<=120&&x.kind==='point'&&typeof x.latitude==='number'&&Number.isFinite(x.latitude)&&Math.abs(x.latitude)<=90&&typeof x.longitude==='number'&&Number.isFinite(x.longitude)&&Math.abs(x.longitude)<=180}
$('#run').onclick=()=>{const o=$('#operation').value,env=$('#env').value,identity=$('#identity').value,rid=$('#requestid').value.trim(),id=/^[A-Za-z0-9._-]{8,64}$/.test(rid)?rid:uuid(),reply=(s,b)=>answer(s,b,id),write=['create','update','delete'].includes(o);if(o==='actuator'){reply('404',{error:'Not found on application port',managementPort:9091,note:'Management endpoints are separate; no management probe is performed.'});return}if(o==='docs'){reply(env==='prod'?'404':'200',env==='prod'?{error:'API documentation disabled in production'}:{notice:'Documentation would be public here in dev/stage. This is not a generated OpenAPI document.',source:'springdoc / code-generated',path:'/api/docs/openapi.json',operationsStillRequireSession:true});return}if(identity==='anonymous'){reply('401',{error:'Authentication required',note:'Actual service uses the backend session established with Keycloak.'});return}if(write&&identity==='viewer'){reply('403',{error:'Editor or admin role required'});return}if(write&&!$('#csrf').checked){reply('403',{error:'CSRF proof required for state-changing requests'});return}if(o==='list'){reply('200',{items:locations,total:locations.length,contract:'Illustrative payload only; no pagination contract supplied.'});return}const index=locations.findIndex(l=>l.id===$('#locationid').value);if(['read','update','delete'].includes(o)&&index<0){reply('404',{error:'Sample location not found'});return}if(o==='read'){reply('200',locations[index]);return}let entity;if(o!=='delete'){try{entity=JSON.parse($('#body').value)}catch{reply('400',{error:'Malformed JSON'});return}if(!validBody(entity)){reply('400',{error:'Illustrative validation failed',expected:'name: 1–120 chars; kind: point; latitude: -90…90; longitude: -180…180. Numbers must be finite.'});return}entity={name:entity.name.trim(),kind:'point',latitude:entity.latitude,longitude:entity.longitude}}
let eid,action;if(o==='create'){eid=uuid();locations.push({id:eid,...entity});action='location.created'}else if(o==='update'){eid=locations[index].id;locations[index]={id:eid,...entity};action='location.updated'}else{eid=locations[index].id;locations.splice(index,1);action='location.deleted'}audit.push({audit:true,action,entityType:'location',entityId:eid,userId:identity==='admin'?'demo-admin-subject':subject,requestId:id});render();reply(o==='create'?'201':o==='delete'?'204':'200',o==='delete'?{notice:'Illustrative display only; an actual 204 response has no JSON body.'}:{id:eid,...entity,derivedGeography:'POINT('+entity.longitude+' '+entity.latitude+') / SRID 4326'});};
const descriptions={auth:'Keycloak-backed login, backend session and permission mapping. Other modules use only the public top-level auth package.',user:'Application-owned profile/preferences associated with the Keycloak subject. Credentials and role grants remain in Keycloak.',location:'Location storage and CRUD responsibilities. UUID identity, kind discriminator and geographic coordinates are part of the domain.',apidocs:'Code-generated OpenAPI and Swagger UI enabled in dev/stage, disabled in production. Reading docs does not open protected operations.',hello:'Placeholder endpoint identified in the source module list. It does not imply a separate service.',audit:'Named in the source observability section: AuditLog records changes using action, entity type/ID, user and request IDs, not entity content.'};
document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>{$('#moduletitle').textContent=b.dataset.module;$('#modulecopy').textContent=descriptions[b.dataset.module];document.querySelectorAll('[data-module]').forEach(n=>n.classList.toggle('selected',n===b))});
function boundary(){$('#boundaryresult').textContent={api:'ALLOWED CONCEPT · Depend on another module through its top-level package API, keeping the dependency graph acyclic.',internal:'BOUNDARY VIOLATION EXAMPLE · Sub-packages are internal. A real ApplicationModules.verify() test rejects this relationship.',cycle:'CYCLE EXAMPLE · Application modules must form an acyclic dependency graph. A real Modulith verification rejects a dependency cycle.'}[$('#boundary').value]}$('#boundary').onchange=boundary;
$('#point').onclick=()=>{const lat=$('#lat').value.trim(),lng=$('#lng').value.trim(),a=Number(lat),b=Number(lng);$('#pointout').textContent=!lat||!lng||!Number.isFinite(a)||!Number.isFinite(b)||Math.abs(a)>90||Math.abs(b)>180?'Invalid coordinates. Latitude -90…90; longitude -180…180.':'POINT('+b+' '+a+') · SRID 4326 · geography(Point, 4326)'};render();operation();boundary();$('#modulecopy').textContent=descriptions.auth;
